      toast.ok(`v${saved.version} salva.`);
      await Promise.all([keys.pipeline(), keys.versions, keys.state].map(queryKey => client.invalidateQueries({ queryKey })));
    } catch (error) { toast.error(error); } finally { setSaving(false); }
  };

  return (
    <>
      <PageHead
