    if (!decision.note.trim()) throw new Error('Registre a justificativa para aceitar os alertas selecionados.');
    const run = await getRun(runId), exceptions = await exceptionsFor(run);
    const selected = [...new Set(ids)].map(id => exceptions.find(exception => exception.id === id));
    if (selected.some(exception => !exception || exception.severity === 'bloqueante')) throw new Error('Exceções bloqueantes precisam ser decididas individualmente.');
    let decided = 0;
    for (const exception of selected) {
      await sendDecision(runId, exception!.id, decision);
